<?php
require_once __DIR__.'/../includes/functions.php';require_role(['admin','super_admin']);$db=db();$today=(int)$db->query('SELECT COUNT(*) FROM appointments WHERE appointment_date=CURRENT_DATE()')->fetchColumn();$patients=(int)$db->query('SELECT COUNT(*) FROM patients')->fetchColumn();$doctors=(int)$db->query("SELECT COUNT(*) FROM doctors d JOIN users u ON u.id=d.user_id WHERE u.status='active'")->fetchColumn();$unpaid=(int)$db->query("SELECT COUNT(*) FROM invoices WHERE status<>'paid'")->fetchColumn();$rows=$db->query("SELECT a.*,COALESCE(NULLIF(p.full_name,''),pu.name,'Walk-in') patient_name,du.name doctor_name,dep.name department_name FROM appointments a JOIN patients p ON p.id=a.patient_id LEFT JOIN users pu ON pu.id=p.user_id JOIN doctors d ON d.id=a.doctor_id JOIN users du ON du.id=d.user_id JOIN departments dep ON dep.id=d.department_id ORDER BY a.appointment_date DESC,a.start_at DESC LIMIT 8")->fetchAll();$pageTitle='Clinic overview';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/page.php';page_heading('Workspace overview','Clinic operations','Here is what is happening across your clinic today.','<a class="btn btn-primary" href="'.e(url('appointments/book.php')).'"><i class="bi bi-plus-lg me-1"></i>Book appointment</a>');?>
<div class="row g-3 mb-4"><div class="col-6 col-xl-3"><?=stat_card("Today's appointments",(string)$today,'calendar-check','Scheduled for today')?></div><div class="col-6 col-xl-3"><?=stat_card('Patients',(string)$patients,'people','Total registered records')?></div><div class="col-6 col-xl-3"><?=stat_card('Active doctors',(string)$doctors,'person-badge','Clinical team')?></div><div class="col-6 col-xl-3"><?=stat_card('Open invoices',(string)$unpaid,'receipt','Unpaid or partial')?></div></div><div class="card"><div class="card-header d-flex justify-content-between"><h2 class="section-title">Recent appointments</h2><a href="<?=e(url('appointments/index.php'))?>" class="small text-decoration-none">View all <i class="bi bi-arrow-right"></i></a></div><div class="table-responsive"><table class="table"><thead><tr><th>Patient</th><th>Doctor</th><th>Department</th><th>Date / time</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['patient_name'])?></strong><div class="small-muted">Token #<?= (int)$r['token_number']?></div></td><td><?=e($r['doctor_name'])?></td><td><?=e($r['department_name'])?></td><td><?=e($r['appointment_date'])?> · <?=e(substr($r['start_at'],0,5))?></td><td><?=status_badge($r['status'])?></td></tr><?php endforeach;?><?php if(!$rows)echo empty_row(5,'No appointments yet.');?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>